shards = {
    "shard_1": [{"id": "d1", "score": 0.91}, {"id": "d2", "score": 0.72}],
    "shard_2": [{"id": "d3", "score": 0.88}],
    "shard_3": [{"id": "d4", "score": 0.95}, {"id": "d5", "score": 0.60}],
}

def query_single_shard(shard_docs, top_k):
    return sorted(shard_docs, key=lambda d: -d["score"])[:top_k]

def coordinate_query_across_shards(shards, top_k):
    all_partial_results = []
    for shard_name, shard_docs in shards.items():
        partial = query_single_shard(shard_docs, top_k)
        print(f"  {shard_name} returned: {partial}")
        all_partial_results.extend(partial)
    final_ranked = sorted(all_partial_results, key=lambda d: -d["score"])[:top_k]
    return final_ranked

print("Querying each shard in parallel:")
final_results = coordinate_query_across_shards(shards, top_k=2)

print(f"\nFinal merged, ranked results:")
for r in final_results:
    print(f"  {r}")
